obal\\\\n+idempotente e registros de participantes distintos, sem criar uma nova cota;\\\\n+o codigo de erro permanece documentado no contrato para uma futura decisao de\\\\n+produto que defina explicitamente essa regra.\\\\n\\\",\\n+         \\\"additions\\\": 28,\\n+         \\\"deletions\\\": 0\\n+        },\\n+        {\\n+         \\\"filePath\\\": \\\"/Users/yasmindesouza/TrabalhoIA-WomanInTech/api/tool/smoke_m3.dart\\\",\\n+         \\\"relativePath\\\": \\\"api/tool/smoke_m3.dart\\\",\\n+         \\\"type\\\": \\\"update\\\",\\n+         \\\"patch\\\": \\\"Index: /Users/yasmindesouza/TrabalhoIA-WomanInTech/api/tool/smoke_m3.dart\\\\n===================================================================\\\\n--- /Users/yasmindesouza/TrabalhoIA-WomanInTech/api/tool/smoke_m3.dart\\\\n+++ /Users/yasmindesouza/TrabalhoIA-WomanInTech/api/tool/smoke_m3.dart\\\\n@@ -34,9 +34,9 @@\\\\n final response = await request('POST', '/atividades', user: 'org-ana', body: {\\\\n   'titulo': title,\\\\n   'tipo': 'palestra',\\\\n   'salaId': title == 'Primeira' ? 'sala-101' : 'sala-102',\\\\n-  'vagas': 2,\\\\n+   'vagas': 3,\\\\n   'encontros': [\\\\n     {\\\\n       'inicio': '${day}T09:00:00-03:00',\\\\n       'fim': '${day}T10:00:00-03:00',\\\\n@@ -99,8 +99,13 @@\\\\n         'lidoEm': '2026-10-19T08:45:00-03:00',\\\\n       });\\\\n   check(offline.status == 201 && offline.json['origem'] == 'qr_offline',\\\\n       'presenca offline');\\\\n+  await request('POST', '/atividades/$atividade/inscricoes', user: 'p-diego');\\\\n+  final invalid = await request('POST', '/encontros/$encontro/presencas',\\\\n+      user: 'p-diego', body: {'codigo': 'INVALIDO'});\\\\n+  check(invalid.status == 422 && invalid.json['erro'] == 'CODIGO_INVALIDO',\\\\n+      'codigo invalido nao duplicado');\\\\n   final duplicate = await request('POST', '/encontros/$encontro/presencas',\\\\n       user: 'p-carla', body: {'codigo': 'ANTIGO'});\\\\n   check(duplicate.status == 200 && duplicate.json['id'] == q